%[text] ## Portfolio Optimization Engine
%[text] For this simulation It's running 15,000 randomly generated portfolios
%%

clc;
clear;
close all;


run('HistoricalData.m'); %[output:3c807437] %[output:6d3e5de8]


n = length(stocks);


disp("Historical Daily Returns:"); %[output:9f0a646e]

disp(array2table(dailyReturns, ... %[output:group:89d7a020] %[output:30a24d6a]
    'VariableNames',cellstr(stocks))); %[output:group:89d7a020] %[output:30a24d6a]


disp("Expected Annual Returns:"); %[output:40df5a30]

disp(array2table(annualReturns, ... %[output:group:965e5059] %[output:90f17ea7]
    'VariableNames',cellstr(stocks))); %[output:group:965e5059] %[output:90f17ea7]


disp("Annual Covariance Matrix:"); %[output:2adeefb0]

disp(array2table(annualCovariance, ... %[output:group:8231804f] %[output:3abcf2d6]
    'VariableNames',cellstr(stocks), ... %[output:3abcf2d6]
    'RowNames',cellstr(stocks))); %[output:group:8231804f] %[output:3abcf2d6]

%%
%[text] Portfolio risk was calculated using the portfolio standard deviation formula

weights = ones(n,1)/n;

portfolioReturn = weights' * annualReturns';

% Calc portfolio risk
portfolioRisk = sqrt(weights' * ...
    annualCovariance * weights);

disp("Portfolio Annual Return:"); %[output:7c5669ed]
disp(portfolioReturn); %[output:685e08e9]

disp("Portfolio Annual Risk:"); %[output:12e51ad5]
disp(portfolioRisk); %[output:2916c9a4]
%%
%[text] Using the softmax transformation prior to the optimization to weight the portfolios
%[text] Unfortunately this method wont permit exact zero allocations, also MATLAB's fminsearch function only guarantees local(not global) optimum
%[text] Set to 10,000 optimization iterations and 50,000 function evaluations
%[text] Basically pushing the limit
%[text] Removed the largest value from each logit to minimize noise later


% initial equal allocation
z0 = zeros(n-1,1);


options = optimset('Display','iter', ...
    'MaxIter',10000, ...
    'MaxFunEvals',50000);

% run optimization
zOptimal = fminsearch(@(z) portfolioObjective(z, annualCovariance), ... %[output:group:89f3fe86] %[output:0a6cb1d4]
    z0, options); %[output:group:89f3fe86] %[output:0a6cb1d4]

% convert optimized variables to portfolio weights
logits = [zOptimal(:); 0];
logits = logits - max(logits);

optimalWeights = exp(logits) / sum(exp(logits));

% calc minimum portfolio variance
minimumVariance = optimalWeights' * annualCovariance * optimalWeights;

disp("Optimal Stock Allocations:"); %[output:0fcc51a7]

disp(array2table(optimalWeights', ... %[output:group:36e877b9] %[output:1a43ead7]
    'VariableNames', matlab.lang.makeValidName(cellstr(stocks)))); %[output:group:36e877b9] %[output:1a43ead7]

fprintf('Minimum Portfolio Variance: %.8f\n', minimumVariance); %[output:46d361f8]

% objective function
function variance = portfolioObjective(z, annualCovariance)

logits = [z(:); 0];
logits = logits - max(logits);

w = exp(logits) / sum(exp(logits));

variance = w' * annualCovariance * w;

end
%%
%[text] Risk free rate is set to a our current 4.22%
%%
% Calc optimized portfolio return
optimalReturn = optimalWeights' * annualReturns';

% calc optimized portfolio risk
optimalRisk = sqrt(optimalWeights' * ...
    annualCovariance * optimalWeights);

% Sharpe ratio
riskFreeRate = 0.0422;

sharpeRatio = (optimalReturn-riskFreeRate) ...
    / optimalRisk;

disp("OPTIMIZED PORTFOLIO RESULTS"); %[output:756d40b2]

fprintf("Expected Annual Return: %.2f%%\n", ... %[output:group:2ddde8e7] %[output:251d842b]
    optimalReturn*100); %[output:group:2ddde8e7] %[output:251d842b]

fprintf("Annual Risk: %.2f%%\n", ... %[output:group:30007647] %[output:868e10a7]
    optimalRisk*100); %[output:group:30007647] %[output:868e10a7]

fprintf("Sharpe Ratio: %.4f\n", sharpeRatio); %[output:09ff01e8]
%%



numPortfolios = 15000;
riskFreeRate = 0.04;

rng(42);

% random portfolio generation

randomWeights = rand(numPortfolios,n);

% Normalize weights to  100%
randomWeights = randomWeights ./ sum(randomWeights,2);

% calculate portfolio returns
simulatedReturns = randomWeights * annualReturns';

% calc portfolio risks
simulatedRisks = sqrt(sum( ...
    (randomWeights * annualCovariance) .* ...
    randomWeights,2));

% Calc sharpe ratios
simulatedSharpe = ...
    (simulatedReturns-riskFreeRate) ./ simulatedRisks;


% select the best portfolio from the simulation

[~,bestIndex] = max(simulatedSharpe);

tangencyWeights = randomWeights(bestIndex,:)';

tangencyReturn = simulatedReturns(bestIndex);

tangencyRisk = simulatedRisks(bestIndex);

tangencySharpe = simulatedSharpe(bestIndex);

% individual stats

stockReturns = annualReturns';

stockRisks = sqrt(diag(annualCovariance));

%%\ CML

cmlRisk = linspace(0,max(simulatedRisks)*1.1,100);

cmlReturn = riskFreeRate + tangencySharpe*cmlRisk;
%%
%[text] Calc for efficient frontier

% generate target returns from simulated portfolios
targetReturns = linspace( ...
    min(simulatedReturns), ...
    max(simulatedReturns),100);

frontierRisk = zeros(length(targetReturns),1);

for i = 1:length(targetReturns)

    eligible = find(simulatedReturns >= targetReturns(i));

    if isempty(eligible)
        frontierRisk(i) = NaN;
    else
        frontierRisk(i) = min(simulatedRisks(eligible));
    end

end

% Remove invalid points function
valid = ~isnan(frontierRisk);

frontierRisk = frontierRisk(valid);
targetReturns = targetReturns(valid);


%%
%[text] Plotting functions


figure('Color','w','Position',[100 100 1200 750]); %[output:4ceb6c59]

hold on; %[output:4ceb6c59]
grid on; %[output:4ceb6c59]
box on; %[output:4ceb6c59]

%%\ monte carlo portfolio cloud

scatter(simulatedRisks*100, ... %[output:4ceb6c59]
    simulatedReturns*100, ... %[output:4ceb6c59]
    12, simulatedSharpe, 'filled'); %[output:4ceb6c59]

colormap(jet); %[output:4ceb6c59]

cb = colorbar; %[output:4ceb6c59]
ylabel(cb,'Sharpe Ratio'); %[output:4ceb6c59]

% efficient Frontier

plot(frontierRisk*100, ... %[output:4ceb6c59]
    targetReturns*100, ... %[output:4ceb6c59]
    'r-', 'LineWidth',3); %[output:4ceb6c59]

%%\ MVPortfolio

minReturn = optimalWeights' * annualReturns';

minRisk = sqrt( ...
    optimalWeights' * annualCovariance * optimalWeights);

plot(minRisk*100, ... %[output:4ceb6c59]
    minReturn*100, ... %[output:4ceb6c59]
    'b*', 'MarkerSize',18, 'LineWidth',2); %[output:4ceb6c59]

% tangency portfolio

plot(tangencyRisk*100, ... %[output:4ceb6c59]
    tangencyReturn*100, ... %[output:4ceb6c59]
    'p', 'MarkerSize',18, ... %[output:4ceb6c59]
    'MarkerFaceColor','y', ... %[output:4ceb6c59]
    'MarkerEdgeColor','k'); %[output:4ceb6c59]

% Capital Market Line

plot(cmlRisk*100, ... %[output:4ceb6c59]
    cmlReturn*100, ... %[output:4ceb6c59]
    'k--', 'LineWidth',1.8); %[output:4ceb6c59]

% Individual stocks

plot(stockRisks*100, ... %[output:4ceb6c59]
    stockReturns*100, ... %[output:4ceb6c59]
    ['d'], ... %[output:4ceb6c59]
    'MarkerSize',10, ... %[output:4ceb6c59]
    'MarkerFaceColor','w', ... %[output:4ceb6c59]
    'MarkerEdgeColor','r', ... %[output:4ceb6c59]
    'LineWidth',1.8); %[output:4ceb6c59]

% labels

for i = 1:n

    text(stockRisks(i)*100+0.3, ... %[output:4ceb6c59]
        stockReturns(i)*100, ... %[output:4ceb6c59]
        char(stocks(i)), ... %[output:4ceb6c59]
        'FontSize',10, ... %[output:4ceb6c59]
        'FontWeight','bold',... %[output:4ceb6c59]
        'Color',[0 0 0]); %[output:4ceb6c59]

end

% pretty graph stuff

xlabel('Annual Portfolio Risk (%)', ... %[output:4ceb6c59]
     'Color',[0 0 0], ... %[output:4ceb6c59]
    'FontSize',13); %[output:4ceb6c59]

ylabel('Annual Expected Return (%)', ... %[output:4ceb6c59]
     'Color',[0 0 0], ... %[output:4ceb6c59]
    'FontSize',13); %[output:4ceb6c59]

title('Efficient Frontier with Capital Market Line', ... %[output:4ceb6c59]
     'Color',[0 0 0], ... %[output:4ceb6c59]
    'FontSize',16); %[output:4ceb6c59]

legend('Simulated Portfolios', ... %[output:4ceb6c59]
    'Efficient Frontier', ... %[output:4ceb6c59]
    'Minimum Variance', ... %[output:4ceb6c59]
    'Tangency (Max Sharpe)', ... %[output:4ceb6c59]
    'Capital Market Line', ... %[output:4ceb6c59]
    'Individual Stocks', ... %[output:4ceb6c59]
    'Location','northoutside',... %[output:4ceb6c59]
    'Color',[1 1 1], ... %[output:4ceb6c59]
    'TextColor',[0 0 0]); %[output:4ceb6c59]

cb = colorbar; %[output:4ceb6c59]
set(cb,'Color',[0 0 0]); %[output:4ceb6c59]
ylabel(cb,'Sharpe Ratio','Color',[0 0 0]); %[output:4ceb6c59]

set(gca,'XColor',[0 0 0], ... %[output:4ceb6c59]
    'YColor',[0 0 0]); %[output:4ceb6c59]

set(gca,'Color',[1 1 1]); %[output:4ceb6c59]

set(gca,'GridColor',[0 0 0], ... %[output:4ceb6c59]
    'GridAlpha',0.3); %[output:4ceb6c59]

set(gca,'FontSize',11) %[output:4ceb6c59]
hold off; %[output:4ceb6c59]

%%\ DISP

fprintf('\nPORTFOLIO OPTIMIZATION RESULTS\n'); %[output:7384fd71]

fprintf('Minimum Variance Risk: %.2f%%\n',minRisk*100); %[output:99fbbcb1]

fprintf('Minimum Variance Return: %.2f%%\n',minReturn*100); %[output:67e016b9]

fprintf('Tangency Portfolio Risk: %.2f%%\n',tangencyRisk*100); %[output:2fec6728]

fprintf('Tangency Portfolio Return: %.2f%%\n',tangencyReturn*100); %[output:181530ba]

fprintf('Tangency Sharpe Ratio: %.4f\n',tangencySharpe); %[output:96941106]

saveas(gcf,'efficient-frontier.png'); %[output:4ceb6c59]

